s["UIMouseOutAlpha"] ) * 100	end, function(val)		self.Settings["UIMouseOutAlpha"] = (val / 100)		if WYK_WarTools_StrategyUI ~= nil then			WYK_WarTools_StrategyUI:SetOutAlpha( val / 100 )			WYK_WarTools_StrategyUI.Backdrop:SetAlpha( val / 100 )		end	end)	self:AddMenuSlider("Fade % When Mouse Over", nil, 0, 100, 1, function()		return self:GetOrDefault( .85, self.Settings["UIMouseInAlpha"] ) * 100	end, function(val)		self.Settings["UIMouseInAlpha"] = (val / 100)		if WYK_WarTools_StrategyUI ~= nil then			WYK_WarTools_StrategyUI:SetInAlpha( val / 100 )		end	end)endWYK_WarTools.Initialize = function( self )	self:SlashCommand("wt", self.CommandLine)	self:SlashCommand("warcommand", self.ToggleCommand)		self.UserInterface.CreateStrategyFrame()endREGISTER_WYKKYD_FACTORY( 	WYK_WarTools, false, true, 	function( self ) self:LoadSavedVariables() end, 	function( self ) self:LoadSettingsMenu() end, 	function( self ) self:Initialize() end )